<?php
$doc = new DOMDocument(); $doc->loadXML('<r/>'); $xp = new DOMXPath($doc);
$nums = ['0.00001','0.0001','0.001','0.0001234','1e-300','1e-15','1.5e-7','123456789012345','1000000000000000','999999999999999','9999999999999999',
 '1234567890123456','0.1e-2','-0.000001','-1e-5','1e-5 * 1','0.00001 * 3','1 div 3 * 1e-5','2 div 3 * 1e20','1e308 * 10','-1e308 * 10',
 '0.5','0.25','123.0','1e10','12345678.9','0.30000000000000004','1.0000000000000002','4.94e-324','2.2250738585072014e-308','1e-320', '1e-100', '1e-16', '1e-17', '1.23e-5',
 '0.1 * 3', '1 div 3 * 3', '100000000000000', '1e14 + 0.5', '1e15 + 0.5', '123456.7890123456', '0.000123456789012345678', '-123456789012345678', '1e-5 * 7', '0.00009', '0.000099999',
 '1.5e300', '12.5e-3', '7e-7', '1e-6 * 1.5'];
foreach ($nums as $n) { echo str_pad($n, 30), " => ", $xp->evaluate("string($n)"), "\n"; }
libxml_use_internal_errors(true);
foreach (['$var', 'node(1)', 'processing-instruction(1)', '1.', '.5', '..5', '1e5', '1 e5', 'concat()', '"a" | "b"', '//*[1.5]', '//*["a"]', '//*[true()]', '//r[0]'] as $e) {
  libxml_clear_errors();
  $r = $xp->evaluate($e);
  echo str_pad($e, 30), " => ", var_export($r instanceof DOMNodeList ? "nodelist(".$r->length.")" : $r, true), "\n";
  foreach (libxml_get_errors() as $er) echo "    ", $er->code, " ", json_encode($er->message), "\n";
}
